rm -f "$t"

# --room の値が無いとき: exit 2、usage を stderr に、stdout は空
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\n' > "$t"
out=$(BOOKINGS=$t bash src/list.sh --room 2>/dev/null); rc=$?
