out=$(BOOKINGS=$t bash src/list.sh --room aoi 2026-13-01 2>/dev/null); rc=$?
[ "$rc" = 2 ] && [ -z "$out" ] || { echo "list --room with bad date: rc=$rc"; fail=1; }
rm -f "$t"; exit $fail

